use vstd::prelude::*;

verus! {

fn hermemulx(c: Vec<f64>) -> (result: Vec<f64>)
    ensures
        // result has exactly one more element than c
        result.len() == c.len() + 1,
        // first element is 0.0
        result[0] == 0.0,
        // for each original index i, it is moved to result[i+1]
        forall |i: usize| i < c.len() ==> result[i + 1] == c[i],
{
    let n = c.len();
    // pre‐allocate the output vector of length n+1
    let mut result = Vec::with_capacity(n + 1);
    // push the leading 0.0
    result.push(0.0);

    let mut idx: usize = 0;
    // we will push c[0], c[1], …, c[n-1] in order
    while idx < n
        invariant
            // idx runs from 0 up to n
            idx <= n,
            // at each step, we have pushed exactly idx elements
            // after the leading 0.0, so total length is idx+1
            result.len() == idx + 1,
            // the leading element is still 0.0
            result[0] == 0.0,
            // for each j < idx, result[j+1] == c[j]
            forall |j: usize| j < idx ==> result[j + 1] == c[j],
        decreases n - idx,
    {
        // grab the next element from c
        let x = c[idx];
        // append it
        result.push(x);
        // advance
        idx += 1;
    }

    result
}

} // verus!

fn main() {
    // example use
    let a = vec![1.1, 2.2, 3.3];
    let b = hermemulx(a.clone());
    assert!(b.len() == a.len() + 1);
    assert!(b[0] == 0.0);
    for i in 0..a.len() {
        assert!(b[i+1] == a[i]);
    }
}